sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float strength;
uniform float radius;
uniform float feather;
uniform float gaussian;
uniform float style;
float edge(float x) {
    return feather > 0.0 ? smoothstep(0.0, feather, x) : 1.0;
}
half4 main(float2 coord) {
    float2 h = size * 0.5;
    if (style < 0.5) {
        float2 p = (coord - h) / h;
        if (abs(p.x) >= 1.0 || abs(p.y) >= 1.0) return image.eval(coord);
        float2 e = 1.0 - p * p;
        float w = e.x * e.y;
        return image.eval(h + p * (1.0 - strength * 0.6 * w) * h);
    }
    float2 c = center * size;
    float2 d = coord - c;
    float len = length(d);
    float r = max(radius * min(size.x, size.y), 0.0001);
    float u = len / r;
    if (u >= 1.0) return image.eval(coord);
    float a = clamp(strength, -1.0, 1.0);
    float2 to;
    if (a < 0.0) {
        to = c + d / max(len, 0.0001) * (r * (u * u + (1.0 - u) * pow(max(u, 0.0001), 1.0 + 0.75 * a)));
    } else {
        float q = min(gaussian > 0.5 ? pow(u, 4.4) / 0.93 : u * u, 1.0);
        to = c + d * (1.0 - 0.75 * a * (1.0 - q * q * (3.0 - 2.0 * q)));
    }
    float2 p = coord / size;
    return image.eval(coord + (to - coord) * edge(p.x) * edge(1.0 - p.x) * edge(p.y) * edge(1.0 - p.y));
}
